 "headline": "从帐下家奴到太师国王",
 "lead": "木华黎，札剌亦儿氏，世为孛儿只斤家的旧部。生年与少年行事实在疏略，两部底本只记他与孛斡儿出并称「二杰」，又与赤老温、博尔忽合称四杰。旧说称其父孔温窟哇把他交给铁木真作家奴，此说不见于底本，只能存疑。一二〇六年斡难河源大会，他受封左手万户，与右手万户孛斡儿出同统九十五个千户。一二一一年从攻金，连下顺州、高州、成州，降锦州张鲸；一二一五年围北京，收兴中府石天应，凡降者皆以承制授官，辽西、河北的汉军世侯由此成形。一二一七年八月封国王，赐金印、九斿白旗，得专封拜，拜天下兵马大元帅、都行省、太师，金人称为「权皇帝」，任务也从打击金国变为吞并金国。此后取大名、益都，收严实，转攻陕西，一二二二年凤翔受挫，一二二三年三月病卒军中，经略五年半。子孛鲁、孙塔思相继嗣国王，曾孙安童、拜住，五世孙朵儿只皆至宰辅。",
 "points": [
  "转折一：一二〇六年斡难河源分封，他以左手万户与孛斡儿出分统九十五千户，从帐前近侍变成汗的左右手。",
  "转折二：一二一五年围北京，他不许屠城，承制授石天应等降将官职，把降人编成汉军世侯，辽西由此立住。",
  "转折三：一二一七年封国王、赐九斿白旗，专征金国；五年半后病卒军中，凤翔未下，华北军顿失统帅。"
 ],
 "why": [
  {
   "q": "为什么木华黎能从家奴做到太师国王？",
   "a": "因为在草原的制度里，忠诚比血统更值钱。木华黎出自札剌亦儿部，这个部早年与孛儿只斤家有过血仇，后来世为臣属，他的身份本不足以与诸部贵族并列。但他从铁木真最落魄的时候就随侍左右，是可随时差遣的近侍，不是需要谈判的盟友。建国分封时，成吉思汗要的是能替他掌兵、又不会自成一部的人，于是把左手万户交给木华黎，与右手万户孛斡儿出相对。近侍出身的万户，权柄来自汗的信任，也受制于汗的任命，这正是他被一路擢到国王的原因。",
   "basis": {
    "type": "book",
    "text": "《细说元朝》第八章 受推为「成吉思可汗」"
   }
  },
  {
   "q": "为什么木华黎能独当一面经略中原？",
   "a": "因为他会打，也会收。蒙古军初入汉地，攻城之后往往屠掠，城邑因此死守；木华黎在辽西、河北一反此例，降者不杀，承制授以行省、府尹、元帅之职，让投降变成有官可做的买卖。石天应、严实、史氏一族都是这样被收进来的。他又以汉军为前驱、以蒙古千户为骨干，用降人守降地，兵不必全由漠北来。封国王、赐九斿白旗之后，他更有专封拜之权，不必事事奏请，政令可以就地落地。能战使其入，能收使其久，这是他能独当一面的根本。",
   "basis": {
    "type": "book",
    "text": "《细说元朝》第十六章 伐金"
   }
  }
 ],
