 "headline": "从斡难河打到多瑙河",
 "lead": "速不台，兀良合惕氏，生年两部底本未载。札木合称他与哲别、忽必来、者勒蔑为四獒，即成吉思汗帐前四犬，常为先锋。他与者勒蔑同出一门，底本只把二人并列，未言世次，旧说多称其为者勒蔑之弟。建国后即受命追脱黑脱阿诸子，又借西夏收纳桑昆之名初次入侵西夏。一二一九年与哲别各率万骑穷追花剌子模算端，转战里海以西；一二二一年在格鲁吉亚设伏，佯退诱敌，使该国成为蒙古在欧洲的第一个附庸；一二二三年迦勒迦河再破俄罗斯诸公联军，随后在克里米亚休整东返。一二三〇年攻潼关小关，为完颜彝所败，是他横行亚欧的第一次败仗。一二三二年围汴梁，筑长墙百五十里困之，城将下时请屠，被耶律楚材谏止。一二三六年以副统帅佐拔都西征，破莫斯科、弗拉基米尔；一二四一年分兵三路，诱匈牙利军至莫希平原而歼灭之。班师后仍驻漠北，一二四八年卒，年七十三。",
 "points": [
  "转折一：建国之初奉命穷追脱黑脱阿诸子，又借西夏收纳桑昆之名顺势入侵，以先锋之职立住位置。",
  "转折二：一二一九年与哲别各率万骑西追算端，转战里海以西，格鲁吉亚设伏使其成为蒙古在欧洲第一个附庸。",
  "转折三：一二三六年以副统帅佐拔都西征，破莫斯科、弗拉基米尔，一二四一年莫希平原歼灭匈牙利联军。"
 ],
 "why": [
  {
   "q": "为什么成吉思汗把速不台放在先锋的位置上？",
   "a": "因为先锋要的不是资历，是能追、能等、能算。速不台出身边地部族，没有大部众可恃，他的位置全靠战功；而先锋最需要的本事正是长途奔袭与临机设伏，这两样他都有。札木合把帐前四员猛将比作四犬，速不台居其一，说明他在建国之前就已经是常在军前的人。成吉思汗用他，是因为把最险的一段路交给一个没有退路的人，比交给一个有自己的部众、会盘算保存实力的人更可靠。",
   "basis": {
    "type": "book",
    "text": "《细说元朝》第六章 吞并南部乃蛮"
   }
  },
  {
   "q": "为什么速不台能从先锋做到西征副统帅，独当一面？",
   "a": "因为他把先锋的经验变成了战役的设计。先锋只对一段路负责，副统帅要对整场战争负责；速不台的长处是他懂得用退却换地形。格鲁吉亚、迦勒迦河、莫希平原三次大战，都是先佯退、把敌人拖到对自己有利的地方，再一次合围。这种打法不靠兵力优势，靠的是对道路、补给与敌军心理的算计。拔都是名义统帅，实主调度的是速不台，正因为诸系长子各领一路、互不相下，只有这个打了几十年仗的老将能把各路捏在一起。",
   "basis": {
    "type": "book",
    "text": "《成吉思汗与今日世界之形成》第六章 发现欧洲大陆与征服欧洲"
   }
  }
 ],
