 "headline": "从真定世侯到元朝宰相",
 "lead": "史天泽，字润甫，河北永清人，父史秉直，兄史天倪，叔史怀德。史氏为河北大族，金末聚众自保。癸酉年，史家父子叔侄带着本家、亲戚、邻居、朋友一千多人，自动走到涿州军前，向木华黎归降。壮丁编为黑军，由史怀德统领，史天泽自此时为蒙古汉军将领。一二二〇年武仙以真定降蒙古，史天倪为正、武仙为副；一二二五年武仙杀史天倪而据真定，史天泽与蒙古将军肖乃台合兵反复争夺，到一二二六年秋天才把武仙赶走。己丑年朝廷编定汉军三万户，史天泽居其一，统真定一路。一二三〇年卫州之战先败后胜，一二三二年白公庙再破金军。中统初与不花同为都省右丞相；一二六二年围益都、灭李璮，事后自请罢世袭，把汉人世侯的兵交还朝廷。至元二年与安童同为中书右丞相，后改左丞相。一二七五年从伯颜伐宋，病卒军中，年七十四，谥忠武。其生年书中未载，早年行迹也只在父兄的传记里附见。",
 "points": [
  "转折一：癸酉年随父叔携族属千人至涿州归降，壮丁编为黑军，史氏由金末地方大族变成蒙古的汉军世侯。",
  "转折二：一二二五年武仙杀其兄史天倪而据真定，他与肖乃台反复争夺两年，一二二六年秋才收复真定，从此真正据有一路。",
  "转折三：一二六二年平李璮之后自请罢世袭，把世侯之兵交还朝廷，从割据一方的军阀变成忽必烈朝的中书宰相。"
 ],
 "why": [
  {
   "q": "为什么蒙古要起用史氏这样的河北大族？",
   "a": "因为蒙古在河北没有自己的州县。千户兵额有限，南下掠取之后便北还，攻下的城邑守不住；金朝的州县官又多半逃散。地方大族聚族结寨，有粮、有人、有路，谁能给他们名分，他们就替谁守土。史氏携一千多口来降，等于把永清一带的人口与关系网整个交出来，木华黎要的正是这个。用降人守降地，比从漠北派官便宜得多，也比硬攻每一座坞堡快得多。史氏因此被编为黑军，成为蒙古在河北的第一批汉军世侯。",
   "basis": {
    "type": "book",
    "text": "《细说元朝》第十六章 伐金"
   }
  },
  {
   "q": "为什么他后来要主动交出世侯之权？",
   "a": "因为他看得懂李璮之叛意味着什么。世侯兼管军民、世袭其职，本是蒙古兵力不足时的权宜之计；忽必烈即位后要集权，山东一叛，河北的世侯便都在嫌疑之中。若等朝廷来削，削去的不只是权，可能还有族。史天泽先自请罢世袭，把兵交出去，既表明无割据之心，也替史氏换来在新朝的位置。他因此得忽必烈信任，入为中书右丞相。主动退一步，是为全族留一条路。",
   "basis": {
    "type": "book",
    "text": "《细说元朝》第十九章 宋与蒙古之间、第二十章 蒙古汉军"
   }
  }
 ],
