MR.people["yuan:wentianxiang"] = {
 "headline": "状元宰相：不写一字降书的宋末孤臣",
 "lead": "文天祥，吉州庐陵人，生年书中作宋理宗端平三年。家世底本未详，只记他是一个十足的文人，生平不曾受过军事教育，也不曾怎样在兵法与战史的书上下过功夫。宝祐四年他应进士举，殿试第一，中了状元，是南宋末的状元宰相。德祐二年正月二十日，他以右丞相兼枢密使、都督的身份，与左丞相吴坚同赴伯颜军中议和，因态度倔强被扣；随后又被伯颜加进赴上都的祈请使之列，五个人一同押解北上。船抵镇江，他与杜浒等一班义从设法脱走，历真州、扬州、高邮，备尝艰险，最后由南通州航海南归。景炎元年六月十七日到温州，转赴行朝，受任右丞相，在外发展，号召忠义，江淮闽广的应者甚众，与张世杰、陆秀夫并为宋末三柱石。景炎二年八月兵溃于庐陵以南的方石岭与空坑，败在李恒之手，退汀州、循州，再驻潮州。祥兴元年十二月退守海丰五坡岭，为张弘正所掳。押至崖山，张弘范迫他作书招降张世杰，他不书一字；崖山战后解到大都，囚在兵马司一间没有窗户的土屋里整整三年。忽必烈许以宰相，他答愿以一死报国，至元十九年末被杀于柴市，年四十七。",
 "points": [
  "转折一：以状元入仕，由文臣一路升到右丞相兼枢密使，手中却没有一兵一卒。",
  "转折二：奉使伯颜军中因倔强被扣，列入祈请使押解北上，在镇江脱走，历真州、扬州、高邮南归。",
  "转折三：空坑兵溃、五坡岭被掳，押至崖山不书一字，大都土屋三年，许以宰相而不受。"
 ],
 "why": [
  {
   "q": "为什么南宋末年会把局面交给一个不曾习兵的文人？",
   "a": "因为到德祐年间，朝廷已经没有可倚仗的武将了。襄阳既失，长江上游尽归蒙古，能战的老将或死或降，剩下的是文臣与清议。状元是文臣里名望最高的一档，中第即入清望，升迁远快于寻常进士；危难之际，朝廷要的不是一个懂兵法的人，是一个名足以号召、身足以表率的人。文天祥的长处正在这里：他不曾受过军事教育，也不曾在兵法战史上用过功夫，却肯把这条命押上去，江淮闽广的忠义之士因此愿意跟着他走。",
   "basis": {
    "type": "book",
    "text": "《细说元朝》第十九章 宋与蒙古之间"
   }
  },
  {
   "q": "为什么元廷许以宰相之位，仍然买不动文天祥？",
   "a": "因为他一旦受官，前面几年的路就全成了假的。他在元营里不肯低头被扣，在镇江冒死脱走，在闽广屡败而再起，靠的都是不降这一个名分；受了宰相，等于承认宋室的覆亡合理，也等于把死在他前后的那些人一并否掉。忽必烈要的是借他的降服收江南人心，他看得清楚，所以只肯以一死报国。底本记忽必烈心中最佩服的人正是他，说的是连对手也知道，这样的人不能以官爵收买。",
   "basis": {
    "type": "book",
    "text": "《细说元朝》第四十五章 宋末诸儒"
   }
  }
 ],
 "gap": [
  "文天祥的家世、早年师承与赣州募兵勤王的经过，底本皆未载",
  "他在狱中所作的文字，本书未曾收录，《正气歌》之名不见于底本",
  "被杀的月份，底本一处作至元十九年十月，一处作年末，两说并存"
 ],
 "quotes": []
};
