    "a": "因为他一旦受官，前面几年就全成了假的。他在元营里不肯低头被扣，在镇江冒死脱走，在闽广屡败而再起，靠的都是不降这一个名分；受了宰相，等于承认宋室的覆亡合理，也等于把这些年死在他前后的那些人一并否掉。忽必烈要的是借他的降服收江南人心，他看得清楚，所以只肯以一死报国。底本把这件事记在最佩服的人一节里，说的是连对手也知道，这样的人不能以官爵收买。",
