   "a": "因为他的权没有制度根基，只有拥立之功与兵权两层，两层都随人而存。文宗一死，皇位按遗命要回到明宗一系，他便从拥立者变成挡路的人；他立七岁的宁宗、百计阻挠明宗长子，正是知道自己一旦失去皇帝庇护便无处可立。元统元年他一死，顺帝即位，答纳失里为后也保不住家门：子唐其势、女答纳失里、弟答憐答里先后被杀。钦察一门三世的名将之资，抵不过一朝天子换人。他的结局说明，靠兵变拥立得来的位置，最终也只能被另一场清算收走。",
