 "headline": "逐伯颜、修三史，终死贬途",
 "lead": "脱脱，蔑儿乞惕氏，父马札儿台是伯颜的同胞弟弟。他少从吴直方读书，颇受儒家思想的影响，常在政事上袒护汉人南人，渐渐引起伯颜的疑忌。元统二年，他做惠宗妥懽帖睦尔的宿卫，兼同知枢密院事；后至元元年改兼御史大夫，开始预闻朝政。后至元六年二月，他乘伯颜出猎柳林，关闭大都城门，请惠宗下诏免去伯颜的本兼各职，贬为河南行省左丞相，伯颜走到中途死在龙兴路。父亲马札儿台继为右丞相，八个月后辞职，相位由他接任。至正元年，他恢复伯颜停掉的科举，弛汉人南人养马之禁，蠲免人民积欠的田赋，设局纂修辽金宋三朝正史，时号更化。至正三年以右丞相领三史都总裁，《宋史》四百九十六卷，是纪传体正史里卷数最多的一部。四年五月罢相，家居五年有余，九年闰七月再起为右丞相，十年铸至正通宝。十一年用贾鲁治河，征夫十五万、兵二万，工成而民力大竭；十二年破徐州而屠其城。十四年十一月围高邮，哈麻进谗，惠宗临阵夺其兵，安置淮安，再贬亦集乃路、大理；十五年十二月哈麻矫诏令他饮鸩，年四十二，后来朝廷复其官爵，谥忠献。",
 "points": [
  "转折一：以伯颜亲侄的身份闭城夺相位，既自救全家，也替惠宗收回了被架空的皇权。",
  "转折二：至正元年翻尽伯颜旧政，复科举、弛马禁、修三史，号为更化，却补不上国库的窟窿。",
  "转折三：开河与变钞掏空民力，高邮城下被临阵夺兵，最后以一杯矫诏之酒收场。"
 ],
